type StudyGroup = {
  title: string
  askLeft: string
  askRight: string
  links: [string, string][]
}

type MatchTask = {
  prompt: string
  explanation: string
  pairs: [string, string][]
}

type ChoiceTask = { type: 'choice'; prompt: string; options: string[]; correct: number; explanation: string; image?: { src: string; alt: string } }
type MatchingTask = { type: 'matching'; prompt: string; pairs: [string, string][]; options: string[]; explanation: string }
type MultiTask = { type: 'multi'; prompt: string; options: string[]; correct: string[]; explanation: string }
type ChronologyTask = { type: 'chronology'; prompt: string; events: string[]; correct: string[]; explanation: string }
type Task = ChoiceTask | MatchingTask | MultiTask | ChronologyTask

const answerLetters = ['А', 'Б', 'В', 'Г', 'Д']

function matchingOptionOrder(options: string[], seed: number) {
  return [...options].sort((left, right) => {
    const hash = (value: string) => [...value].reduce((total, char) => (total * 31 + char.charCodeAt(0) + seed) >>> 0, seed + 17)
    return hash(left) - hash(right)
  })
}

function makeMatchingOptions(task: MatchTask, allTasks: MatchTask[], taskIndex: number) {
  const correctAnswers = task.pairs.map(([, answer]) => answer)
  const leftTokens = task.pairs.flatMap(([left]) => left.toLocaleLowerCase('uk').match(/[а-яіїєґ]{4,}/giu) ?? [])
  const distractors = allTasks
    .filter((_, index) => index !== taskIndex)
    .flatMap((candidate) => candidate.pairs.map(([, answer]) => answer))
    .filter((answer) => !correctAnswers.includes(answer))
    .map((answer, index) => ({
      answer,
      overlap: leftTokens.filter((token) => answer.toLocaleLowerCase('uk').includes(token)).length,
      index,
    }))
    .sort((left, right) => left.overlap - right.overlap || left.index - right.index)
  const distractor = distractors[0]?.answer
  const options = [...correctAnswers, distractor ?? 'Жодна з наведених відповідей']
  const seed = taskIndex + [...task.prompt].reduce((sum, char) => sum + char.charCodeAt(0), 0)
  return matchingOptionOrder(options, seed)
}

export const historyTopicTenMistakesKey = 'nmt-hub:history:topic:10:mistakes'
export const historyTopicMistakesKey = (topicId: number) => `nmt-hub:history:topic:${topicId}:mistakes`

function readMistakeIds(topicId = 10) {
  try {
    const saved = JSON.parse(localStorage.getItem(historyTopicMistakesKey(topicId)) || '[]')
    return Array.isArray(saved) ? saved.filter((id): id is number => Number.isInteger(id) && id >= 0 && id < 100) : []
  } catch {
    return []
  }
}

